const cn = (...classes: Array<string | false | null | undefined>) => classes.filter(Boolean).join(" ");

function Logo({ light = false }: { light?: boolean }) {
  return (
    <div className={cn("flex items-center gap-2.5", light ? "text-white" : "text-[#12211d]")}>
      <span className={cn("grid h-8 w-8 place-items-center rounded-[10px] text-sm font-black", light ? "bg-[#f3bd47] text-[#12211d]" : "bg-[#173b33] text-[#f3bd47]")}>V</span>
      <span className="text-[17px] font-semibold tracking-[-0.035em]">VerifiedNest</span>
    </div>
  );
}

function StatusBadge({ status, onClick }: { status: Listing["verified"]; onClick?: () => void }) {
  const tone = verificationTone(status);
  const styles = {
    verified: "border-[#b7ddca] bg-[#effaf3] text-[#26734b]",
    partial: "border-[#ebd5a7] bg-[#fff8e9] text-[#92621a]",
    pending: "border-[#dcd7cf] bg-[#f8f7f4] text-[#6e6a63]",
    attention: "border-[#f0c1bb] bg-[#fff1ef] text-[#a34035]",
  }[tone];
  return (
    <button onClick={onClick} className={cn("inline-flex items-center gap-1.5 rounded-full border px-2.5 py-1 text-[11px] font-semibold tracking-[0.01em] transition-transform active:scale-[0.97]", styles)}>
      {status === "Verified" ? <ShieldCheck className="h-3.5 w-3.5" /> : status === "Pending" ? <Clock3 className="h-3.5 w-3.5" /> : <AlertTriangle className="h-3.5 w-3.5" />}
      {status}
    </button>
  );
}

function MatchBadge({ value }: { value: number }) {
  return <span className="inline-flex items-center gap-1 rounded-full border border-[#c8e2d1] bg-[#f0faf4] px-2.5 py-1 text-[11px] font-semibold text-[#24754a]"><Sparkles className="h-3.5 w-3.5" />{value}% match</span>;
}

